@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

@prefix cdifniaid: <https://w3id.org/cdif/niaid/terms/> .
@prefix nde: <https://discovery.biothings.io/ns/nde/> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:DefinedTerm ;
                    schema1:alternateName "Home sapiens",
                        "Homo sampiens",
                        "Homo sapeins",
                        "Homo sapian",
                        "Homo sapians",
                        "Homo sapien",
                        "Homo sapience",
                        "Homo sapiens Linnaeus, 1758",
                        "Homo sapiense",
                        "Homo sapients",
                        "Homo sapines",
                        "Homo spaiens",
                        "Homo spiens",
                        "Human",
                        "Humo sapiens",
                        "human" ;
                    schema1:identifier "9606" ;
                    schema1:inDefinedTermSet "UniProt" ;
                    schema1:name "Homo sapiens" ;
                    schema1:url "https://www.uniprot.org/taxonomy/9606" ;
                    nde:isCurated "yes" ;
                    nde:originalName "Homo Sapiens (human)" ;
                    cdifniaid:classification "host" ;
                    cdifniaid:commonName "Human" ;
                    cdifniaid:displayName "Human | Homo sapiens" ] ;
            sh:resultMessage "nde:isCurated must be a single boolean." ;
            sh:resultPath nde:isCurated ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:boolean ;
                    sh:maxCount 1 ;
                    sh:message "nde:isCurated must be a single boolean." ;
                    sh:path nde:isCurated ;
                    sh:severity sh:Violation ] ;
            sh:value "yes" ] .

@prefix nde: <https://discovery.biothings.io/ns/nde/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://data.niaid.nih.gov/resources?id=pxd027351> ;
            sh:resultMessage "nde:nctid must be a ClinicalTrials.gov id: NCT and eight digits." ;
            sh:resultPath nde:nctid ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:PatternConstraintComponent ;
            sh:sourceShape [ sh:message "nde:nctid must be a ClinicalTrials.gov id: NCT and eight digits." ;
                    sh:path nde:nctid ;
                    sh:pattern "^NCT[0-9]{8}$" ;
                    sh:severity sh:Violation ] ;
            sh:value "12345" ] .

